function Invoke-MeridianBackups {
  param([string]$SqlInstance = "MERSQLPRD01")
  try {
    Backup-DbaDatabase -SqlInstance $SqlInstance `
      -Database MeridianCommerce -Type Full `
      -Path \\MERBACKUP01\SQLBackups\MeridianCommerce
    Test-DbaLastBackup -SqlInstance $SqlInstance `
      -Database MeridianCommerce
  }
  catch { Send-MeridianAlert -Severity Critical -Message $_ }
}

function Invoke-MeridianIndexMaintenance {
  param([string]$SqlInstance = "MERSQLPRD01")
  try {
    Invoke-DbaDbIndexOptimize -SqlInstance $SqlInstance `
      -Database MeridianCommerce
  }
  catch {
    Send-MeridianAlert -Severity Warning -Message $_
  }
}
